def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    wall = next(v for row in grid for v in row if v != bg)

    # The two filled bands lie between pairs of parallel descending diagonals.
    diagonals = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall:
                diagonals.setdefault(r + c, set()).add(r)

    fills = set()
    for lo, hi in ((7, 15), (19, 24)):
        if lo not in diagonals or hi not in diagonals:
            continue
        common_rows = diagonals[lo] & diagonals[hi]
        for r in common_rows:
            left, right = lo - r, hi - r
            for c in range(left + 1, right):
                if 0 <= c < w and grid[r][c] == bg:
                    fills.add((r, c))

    out = [row[:] for row in grid]
    for r, c in fills:
        out[r][c] = 2
    return out
